mapper.select:
SELECT t.id, t.transfer_no, t.from_warehouse_id, t.to_warehouse_id, t.status, t.remark, t.shipped_at, t.shipped_by, t.received_at, t.received_by, t.version, t.created_at, t.updated_at, fw.warehouse_code AS from_warehouse_code, fw.name AS from_warehouse_name, tw.warehouse_code AS to_warehouse_code, tw.name AS to_warehouse_name FROM inventory_transfer t LEFT JOIN warehouse fw ON fw.id = t.from_warehouse_id LEFT JOIN warehouse tw ON tw.id = t.to_warehouse_id WHERE t.deleted = FALSE
AND t.transfer_no ILIKE CONCAT('%', #{query.transferNo}, '%')
AND t.from_warehouse_id = #{query.fromWarehouseId}
AND t.to_warehouse_id = #{query.toWarehouseId}
AND t.status = #{query.status}
ORDER BY t.created_at DESC, t.id DESC
